package com.niranjan.medqueue.contact

import android.content.ActivityNotFoundException
import android.content.Context
import android.content.Intent
import android.net.Uri
import androidx.core.net.toUri
import com.niranjan.medqueue.data.settings.AppSettings
import java.net.URLEncoder
import java.nio.charset.StandardCharsets

// ── Types ─────────────────────────────────────────────────────────────────────

enum class ContactAction { WHATSAPP, SMS, CALL }

sealed class ContactActionResult {
    object Success              : ContactActionResult()
    object InvalidPhone         : ContactActionResult()
    object WhatsAppNotInstalled : ContactActionResult()
    object NoHandler            : ContactActionResult()
}

// ── Message builder (single source of truth) ─────────────────────────────────

/**
 * Builds the standard availability message.
 * All 3 contact actions reuse this — no duplication.
 */
fun buildMessage(customerName: String, medicineName: String): String =
    "Hello $customerName, your $medicineName is now available. Please visit."

// ── Action dispatcher ─────────────────────────────────────────────────────────

fun launchContactAction(
    context: Context,
    action: ContactAction,
    phone: String,
    message: String
): ContactActionResult {
    if (phone.isBlank()) return ContactActionResult.InvalidPhone

    return when (action) {
        ContactAction.WHATSAPP -> launchWhatsApp(context, phone, message)
        ContactAction.SMS      -> launchSms(context, phone, message)
        ContactAction.CALL     -> launchCall(context, phone)
    }
}

// ── Intent helpers ────────────────────────────────────────────────────────────

private fun launchWhatsApp(context: Context, phone: String, message: String): ContactActionResult {
    return try {
        val encoded = URLEncoder.encode(message, StandardCharsets.UTF_8.toString())
        val intent = Intent(Intent.ACTION_VIEW, "https://wa.me/91$phone?text=$encoded".toUri())
            .setPackage("com.whatsapp")
        context.startActivity(intent)
        ContactActionResult.Success
    } catch (e: ActivityNotFoundException) {
        ContactActionResult.WhatsAppNotInstalled
    }
}

private fun launchSms(context: Context, phone: String, message: String): ContactActionResult {
    return try {
        val intent = Intent(Intent.ACTION_VIEW, "sms:$phone".toUri())
            .putExtra("sms_body", message)
        context.startActivity(intent)
        ContactActionResult.Success
    } catch (e: ActivityNotFoundException) {
        ContactActionResult.NoHandler
    }
}

private fun launchCall(context: Context, phone: String): ContactActionResult {
    return try {
        // ACTION_DIAL only — no CALL permission required
        val intent = Intent(Intent.ACTION_DIAL, "tel:$phone".toUri())
        context.startActivity(intent)
        ContactActionResult.Success
    } catch (e: ActivityNotFoundException) {
        ContactActionResult.NoHandler
    }
}

package com.niranjan.medqueue.contact

import android.content.ActivityNotFoundException
import android.content.Context
import android.content.Intent
import android.net.Uri
import androidx.core.net.toUri
import com.niranjan.medqueue.data.settings.AppSettings
import java.net.URLEncoder
import java.nio.charset.StandardCharsets

// ── Types ─────────────────────────────────────────────────────────────────────

enum class ContactAction { WHATSAPP, SMS, CALL }

sealed class ContactActionResult {
    object Success              : ContactActionResult()
    object InvalidPhone         : ContactActionResult()
    object WhatsAppNotInstalled : ContactActionResult()
    object NoHandler            : ContactActionResult()
}

// ── Message builder (single source of truth) ─────────────────────────────────

/**
 * Builds the bilingual (English + Kannada) availability message.
 * All 3 contact actions reuse this — no duplication.
 */
fun buildMessage(settings: AppSettings): String =
    "Hello, your requested medicines are now available at ${settings.shopName}. Please visit the shop." +
    "\n\n" +
    "ನಮಸ್ಕಾರ, ನಿಮ್ಮ ಔಷಧಿಗಳು ಈಗ ${settings.shopName} ನಲ್ಲಿ ಲಭ್ಯವಿದೆ. ದಯವಿಟ್ಟು ಅಂಗಡಿಗೆ ಬನ್ನಿ." +
    "\n\n" +
    "${settings.yogeshName} : ${settings.yogeshPhone}\n" +
    "${settings.ownerName} : ${settings.ownerPhone}"

// ── Action dispatcher ─────────────────────────────────────────────────────────

fun launchContactAction(
    context: Context,
    action: ContactAction,
    phone: String,
    message: String
): ContactActionResult {
    if (phone.isBlank()) return ContactActionResult.InvalidPhone

    return when (action) {
        ContactAction.WHATSAPP -> launchWhatsApp(context, phone, message)
        ContactAction.SMS      -> launchSms(context, phone, message)
        ContactAction.CALL     -> launchCall(context, phone)
    }
}

// ── Intent helpers ────────────────────────────────────────────────────────────

private fun launchWhatsApp(context: Context, phone: String, message: String): ContactActionResult {
    return try {
        val encoded = URLEncoder.encode(message, StandardCharsets.UTF_8.toString())
        val intent = Intent(Intent.ACTION_VIEW, "https://wa.me/91$phone?text=$encoded".toUri())
            .setPackage("com.whatsapp")
        context.startActivity(intent)
        ContactActionResult.Success
    } catch (e: ActivityNotFoundException) {
        ContactActionResult.WhatsAppNotInstalled
    }
}

private fun launchSms(context: Context, phone: String, message: String): ContactActionResult {
    return try {
        val intent = Intent(Intent.ACTION_VIEW, "sms:$phone".toUri())
            .putExtra("sms_body", message)
        context.startActivity(intent)
        ContactActionResult.Success
    } catch (e: ActivityNotFoundException) {
        ContactActionResult.NoHandler
    }
}

private fun launchCall(context: Context, phone: String): ContactActionResult {
    return try {
        // ACTION_DIAL only — no CALL permission required
        val intent = Intent(Intent.ACTION_DIAL, "tel:$phone".toUri())
        context.startActivity(intent)
        ContactActionResult.Success
    } catch (e: ActivityNotFoundException) {
        ContactActionResult.NoHandler
    }
}

package com.niranjan.medqueue

import android.os.Bundle
import android.widget.Toast
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.activity.viewModels
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material.icons.automirrored.filled.List
import androidx.compose.material.icons.automirrored.filled.Send
import androidx.compose.material.icons.filled.Add
import androidx.compose.material.icons.filled.Check
import androidx.compose.material.icons.filled.Close
import androidx.compose.material.icons.filled.Delete
import androidx.compose.material.icons.filled.Edit
import androidx.compose.material.icons.filled.Home
import androidx.compose.material.icons.filled.Person
import androidx.compose.material.icons.filled.Phone
import androidx.compose.material.icons.filled.Search
import androidx.compose.material.icons.filled.Settings
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import com.niranjan.medqueue.data.local.RequestEntity
import com.niranjan.medqueue.data.local.RequestStatus
import com.niranjan.medqueue.contact.ContactAction
import com.niranjan.medqueue.contact.ContactActionResult
import com.niranjan.medqueue.contact.buildMessage
import com.niranjan.medqueue.contact.launchContactAction
import com.niranjan.medqueue.data.settings.AppSettings
import com.niranjan.medqueue.data.settings.SettingsPrefs
import com.niranjan.medqueue.ui.theme.*
import java.text.SimpleDateFormat
import java.util.Calendar
import java.util.Date
import java.util.Locale

// ── Activity ─────────────────────────────────────────────────────────────────

class MainActivity : ComponentActivity() {

    private val viewModel: RequestViewModel by viewModels()

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            MyApplicationTheme {
                val settingsPrefs = remember { SettingsPrefs(this) }
                MedQueueApp(vm = viewModel, settingsPrefs = settingsPrefs)
            }
        }
    }
}

// ── Navigation ────────────────────────────────────────────────────────────────

sealed class Screen {
    object Home         : Screen()
    object RequestList  : Screen()
    object Settings     : Screen()
    data class RequestDetail(val request: RequestEntity) : Screen()
    data class EditRequest(val request: RequestEntity)   : Screen()
}

// ── App root (no outer Scaffold — each screen owns its own) ──────────────────

@Composable
fun MedQueueApp(vm: RequestViewModel, settingsPrefs: SettingsPrefs) {
    var screen: Screen by remember { mutableStateOf(Screen.RequestList) }
    val requests by vm.requests.collectAsState()

    // Shared bottom bar — only shown on the three main screens
    val bottomBar: @Composable () -> Unit = {
        MedQueueBottomBar(
            currentScreen = screen,
            onNavigate    = { screen = it }
        )
    }

    when (val s = screen) {
        Screen.Home -> HomeScreen(
            onSave = { name, phone, medicine ->
                vm.addRequest(name, phone, medicine)
                screen = Screen.RequestList
            },
            onBack    = { screen = Screen.RequestList },
            bottomBar = bottomBar
        )
        Screen.RequestList -> RequestListScreen(
            requests        = requests,
            onAddClick      = { screen = Screen.Home },
            onItemClick     = { screen = Screen.RequestDetail(it) },
            bottomBar       = bottomBar
        )
        is Screen.RequestDetail -> RequestDetailScreen(
            request       = s.request,
            settingsPrefs = settingsPrefs,
            onEdit        = { screen = Screen.EditRequest(s.request) },
            onDelivered   = { vm.markDelivered(s.request.id); screen = Screen.RequestList },
            onDelete      = { vm.deleteRequest(s.request.id); screen = Screen.RequestList },
            onBack        = { screen = Screen.RequestList }
        )
        is Screen.EditRequest -> EditRequestScreen(
            request = s.request,
            onSave  = { name, phone, medicine ->
                vm.updateRequest(s.request.id, name, phone, medicine)
                screen = Screen.RequestList
            },
            onBack  = { screen = Screen.RequestDetail(s.request) }
        )
        Screen.Settings -> SettingsScreen(
            settingsPrefs = settingsPrefs,
            onBack        = { screen = Screen.RequestList },
            bottomBar     = bottomBar
        )
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── FILTER TAG ENUM ─────────────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

enum class FilterTag(val label: String) {
    ALL("All"),
    TODAY("Today"),
    PENDING("Pending"),
    DELIVERED("Delivered")
}

// ══════════════════════════════════════════════════════════════════════════════
// ── BOTTOM NAVIGATION BAR ───────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

@Composable
fun MedQueueBottomBar(currentScreen: Screen, onNavigate: (Screen) -> Unit) {
    NavigationBar(
        containerColor = MaterialTheme.colorScheme.surface,
        tonalElevation = 4.dp
    ) {
        NavigationBarItem(
            selected = currentScreen is Screen.Home,
            onClick  = { onNavigate(Screen.Home) },
            icon     = { Icon(Icons.Filled.Home, contentDescription = "Home") },
            label    = { Text("Home") },
            colors   = NavigationBarItemDefaults.colors(
                selectedIconColor   = MaterialTheme.colorScheme.onPrimary,
                selectedTextColor   = MaterialTheme.colorScheme.primary,
                indicatorColor      = MaterialTheme.colorScheme.primary
            )
        )
        NavigationBarItem(
            selected = currentScreen is Screen.RequestList,
            onClick  = { onNavigate(Screen.RequestList) },
            icon     = { Icon(Icons.AutoMirrored.Filled.List, contentDescription = "Requests") },
            label    = { Text("Requests") },
            colors   = NavigationBarItemDefaults.colors(
                selectedIconColor   = MaterialTheme.colorScheme.onPrimary,
                selectedTextColor   = MaterialTheme.colorScheme.primary,
                indicatorColor      = MaterialTheme.colorScheme.primary
            )
        )
        NavigationBarItem(
            selected = currentScreen is Screen.Settings,
            onClick  = { onNavigate(Screen.Settings) },
            icon     = { Icon(Icons.Filled.Settings, contentDescription = "Settings") },
            label    = { Text("Settings") },
            colors   = NavigationBarItemDefaults.colors(
                selectedIconColor   = MaterialTheme.colorScheme.onPrimary,
                selectedTextColor   = MaterialTheme.colorScheme.primary,
                indicatorColor      = MaterialTheme.colorScheme.primary
            )
        )
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── REQUEST LIST SCREEN ─────────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RequestListScreen(
    requests: List<RequestEntity>,
    onAddClick: () -> Unit,
    onItemClick: (RequestEntity) -> Unit,
    bottomBar: @Composable () -> Unit = {}
) {
    var searchQuery by remember { mutableStateOf("") }
    var activeFilter by remember { mutableStateOf(FilterTag.ALL) }

    // Compute start-of-today once per recomposition
    val todayStart = remember {
        Calendar.getInstance().apply {
            set(Calendar.HOUR_OF_DAY, 0)
            set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
        }.timeInMillis
    }

    val filteredRequests = remember(requests, searchQuery, activeFilter) {
        requests.filter { req ->
            // Search filter
            val matchesSearch = if (searchQuery.isBlank()) true
            else {
                val q = searchQuery.trim().lowercase()
                req.customerName.lowercase().contains(q) ||
                        req.phoneNumber.contains(q)
            }
            // Tag filter
            val matchesTag = when (activeFilter) {
                FilterTag.ALL       -> true
                FilterTag.TODAY     -> req.createdAt >= todayStart
                FilterTag.PENDING   -> req.status == RequestStatus.PENDING
                FilterTag.DELIVERED -> req.status == RequestStatus.DELIVERED
            }
            matchesSearch && matchesTag
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(" MedQueue", fontWeight = FontWeight.Bold) },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = TopBarContainer,
                    titleContentColor = TopBarContent
                )
            )
        },
        bottomBar = bottomBar,
        floatingActionButton = {
            ExtendedFloatingActionButton(
                onClick = onAddClick,
                icon = { Icon(Icons.Filled.Add, contentDescription = null) },
                text = { Text("Add Request") },
                containerColor = MaterialTheme.colorScheme.primary,
                contentColor   = MaterialTheme.colorScheme.onPrimary
            )
        },
        containerColor = MaterialTheme.colorScheme.background
    ) { padding ->
        Column(modifier = Modifier.padding(padding)) {

            // ── Search bar ───────────────────────────────────────────────
            OutlinedTextField(
                value = searchQuery,
                onValueChange = { searchQuery = it },
                placeholder = { Text("Search by name or phone") },
                leadingIcon = {
                    Icon(Icons.Filled.Search, contentDescription = "Search",
                        tint = MaterialTheme.colorScheme.onSurfaceVariant)
                },
                trailingIcon = {
                    if (searchQuery.isNotEmpty()) {
                        IconButton(onClick = { searchQuery = "" }) {
                            Icon(Icons.Filled.Close, contentDescription = "Clear")
                        }
                    }
                },
                singleLine = true,
                shape = RoundedCornerShape(14.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 8.dp)
            )

            // ── Filter chips row ─────────────────────────────────────────
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 4.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                FilterTag.entries.forEach { tag ->
                    FilterChip(
                        selected = activeFilter == tag,
                        onClick = { activeFilter = tag },
                        label = { Text(tag.label, fontWeight = FontWeight.Medium) },
                        colors = FilterChipDefaults.filterChipColors(
                            selectedContainerColor = MaterialTheme.colorScheme.primary,
                            selectedLabelColor = MaterialTheme.colorScheme.onPrimary
                        )
                    )
                }
            }

            // ── List content ─────────────────────────────────────────────
            if (filteredRequests.isEmpty()) {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text(
                            if (requests.isEmpty()) "No requests yet"
                            else "No matching requests",
                            style = MaterialTheme.typography.titleMedium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            if (requests.isEmpty()) "Tap + Add Request to get started"
                            else "Try a different search or filter",
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.outline
                        )
                    }
                }
            } else {
                LazyColumn(
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(filteredRequests, key = { it.id }) { request ->
                        RequestListItem(request = request, onClick = { onItemClick(request) })
                    }
                    // bottom spacer so FAB doesn't overlap last item
                    item { Spacer(modifier = Modifier.height(72.dp)) }
                }
            }
        }
    }
}

// ── List item card ───────────────────────────────────────────────────────────

@Composable
fun RequestListItem(request: RequestEntity, onClick: () -> Unit) {
    val dateFormat = remember { SimpleDateFormat("dd MMM yyyy, hh:mm a", Locale.getDefault()) }
    val displayName = request.customerName.ifBlank { "----" }
    val isPending = request.status == RequestStatus.PENDING

    val cardBg     = if (isPending) CardPendingBg else CardDeliveredBg
    val stripColor = if (isPending) StripePending  else StripeDelivered

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick),
        shape = RoundedCornerShape(14.dp),
        colors = CardDefaults.cardColors(containerColor = cardBg),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Row(modifier = Modifier.fillMaxWidth().height(IntrinsicSize.Min)) {
            // Accent stripe
            Box(
                modifier = Modifier
                    .width(6.dp)
                    .fillMaxHeight()
                    .background(stripColor, RoundedCornerShape(topStart = 14.dp, bottomStart = 14.dp))
            )
            // Content
            Column(
                modifier = Modifier
                    .weight(1f)
                    .padding(start = 12.dp, end = 16.dp, top = 14.dp, bottom = 14.dp)
            ) {
                // Row 1: Name + Status
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = displayName,
                        style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.weight(1f, fill = false)
                    )
                    Spacer(modifier = Modifier.width(10.dp))
                    StatusBadge(status = request.status)
                }

                Spacer(modifier = Modifier.height(10.dp))

                // Row 2: Phone
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        Icons.Filled.Phone,
                        contentDescription = null,
                        modifier = Modifier.size(15.dp),
                        tint = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = request.phoneNumber,
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }

                Spacer(modifier = Modifier.height(6.dp))

                // Row 3: Medicines
                Text(
                    text = "  ${request.medicineName}",
                    style = MaterialTheme.typography.bodyMedium,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    color = MaterialTheme.colorScheme.onSurface
                )

                Spacer(modifier = Modifier.height(10.dp))

                // Row 4: Date
                Text(
                    text = "  ${dateFormat.format(Date(request.createdAt))}",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.outline
                )
            }
        }
    }
}

// ── Status badge (bold orange / green pill) ──────────────────────────────────

@Composable
private fun StatusBadge(status: RequestStatus) {
    val isPending = status == RequestStatus.PENDING
    Surface(
        shape = RoundedCornerShape(20.dp),
        color = if (isPending) StatusPendingBg else StatusDeliveredBg,
        shadowElevation = 1.dp
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 5.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            if (!isPending) {
                Icon(
                    Icons.Filled.Check,
                    contentDescription = null,
                    modifier = Modifier.size(14.dp),
                    tint = StatusDeliveredContent
                )
            }
            Text(
                text = if (isPending) "PENDING" else "DELIVERED",
                style = MaterialTheme.typography.labelSmall.copy(fontWeight = FontWeight.Bold),
                color = if (isPending) StatusPendingContent else StatusDeliveredContent
            )
        }
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── HOME SCREEN (New Request) ───────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreen(onSave: (String, String, String) -> Unit, onBack: () -> Unit, bottomBar: @Composable () -> Unit = {}) {
    val context = LocalContext.current
    var name       by remember { mutableStateOf("") }
    var phone      by remember { mutableStateOf("") }
    var medicine   by remember { mutableStateOf("") }
    var phoneError by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("New Request") },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = TopBarContainer,
                    titleContentColor = TopBarContent,
                    navigationIconContentColor = TopBarContent
                )
            )
        },
        bottomBar = bottomBar
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Customer details card
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    Text(
                        "Customer Details",
                        style = MaterialTheme.typography.titleSmall,
                        color = MaterialTheme.colorScheme.primary
                    )
                    OutlinedTextField(
                        value = name,
                        onValueChange = { name = it },
                        label = { Text("Customer Name (Optional)") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        shape = RoundedCornerShape(12.dp)
                    )
                    OutlinedTextField(
                        value = phone,
                        onValueChange = { raw ->
                            phone = raw.filter { it.isDigit() }
                            if (phone.isNotEmpty()) phoneError = ""
                        },
                        label = { Text("Phone Number") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        isError = phoneError.isNotEmpty(),
                        supportingText = if (phoneError.isNotEmpty()) {
                            { Text(phoneError, color = MaterialTheme.colorScheme.error) }
                        } else null,
                        shape = RoundedCornerShape(12.dp)
                    )
                }
            }

            // Medicine details card
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    Text(
                        "Medicine Details",
                        style = MaterialTheme.typography.titleSmall,
                        color = MaterialTheme.colorScheme.primary
                    )
                    OutlinedTextField(
                        value = medicine,
                        onValueChange = { medicine = it },
                        label = { Text("Medicines") },
                        placeholder = { Text("e.g.\nParacetamol 500mg\nAmoxicillin 250mg") },
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(min = 120.dp),
                        minLines = 4,
                        maxLines = 8,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text),
                        singleLine = false,
                        shape = RoundedCornerShape(12.dp)
                    )
                }
            }

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Button(
                    onClick = {
                        phoneError = ""
                        when {
                            phone.isBlank()    -> phoneError = "Phone number is required"
                            phone.length < 10  -> phoneError = "Enter a valid 10-digit phone number"
                            medicine.isBlank() -> Toast.makeText(context, "Medicine is required", Toast.LENGTH_SHORT).show()
                            else               -> onSave(name, phone, medicine)
                        }
                    },
                    modifier = Modifier
                        .weight(1f)
                        .height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) { Text("Save", fontWeight = FontWeight.Bold) }

                OutlinedButton(
                    onClick = onBack,
                    modifier = Modifier
                        .weight(1f)
                        .height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) { Text("Cancel") }
            }
        }
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── REQUEST DETAIL SCREEN ───────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RequestDetailScreen(
    request: RequestEntity,
    settingsPrefs: SettingsPrefs,
    onEdit: () -> Unit,
    onDelivered: () -> Unit,
    onDelete: () -> Unit,
    onBack: () -> Unit
) {
    val context = LocalContext.current
    var showContactSheet by remember { mutableStateOf(false) }
    val dateFormat = remember { SimpleDateFormat("dd MMM yyyy, hh:mm a", Locale.getDefault()) }
    val displayName = request.customerName.ifBlank { "----" }

    val isPending = request.status == RequestStatus.PENDING

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Request Detail") },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                actions = {
                    IconButton(onClick = onEdit) {
                        Icon(Icons.Filled.Edit, contentDescription = "Edit")
                    }
                    IconButton(onClick = onDelete) {
                        Icon(Icons.Filled.Delete, contentDescription = "Delete",
                            tint = TopBarContent.copy(alpha = 0.7f))
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = TopBarContainer,
                    titleContentColor = TopBarContent,
                    navigationIconContentColor = TopBarContent,
                    actionIconContentColor = TopBarContent
                )
            )
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Customer info card with status-coloured background
            val infoBg = if (isPending) CardPendingBg else CardDeliveredBg
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = infoBg),
                elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
            ) {
                Column(modifier = Modifier.padding(20.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = displayName,
                            style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.Bold),
                            modifier = Modifier.weight(1f, fill = false)
                        )
                        Spacer(modifier = Modifier.width(12.dp))
                        StatusBadge(status = request.status)
                    }
                    Spacer(modifier = Modifier.height(12.dp))
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            Icons.Filled.Phone,
                            contentDescription = null,
                            modifier = Modifier.size(18.dp),
                            tint = MaterialTheme.colorScheme.primary
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = request.phoneNumber,
                            style = MaterialTheme.typography.bodyLarge,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = "  ${dateFormat.format(Date(request.createdAt))}",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.outline
                    )
                }
            }

            // Medicines card
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(modifier = Modifier.padding(20.dp)) {
                    Text(
                        text = " Medicines",
                        style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.primary
                    )
                    Spacer(modifier = Modifier.height(10.dp))
                    Text(
                        text = request.medicineName,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
            }

            // Action buttons
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Button(
                    onClick = { showContactSheet = true },
                    modifier = Modifier.weight(1f).height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Icon(Icons.AutoMirrored.Filled.Send, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Contact", fontWeight = FontWeight.Bold)
                }
                if (isPending) {
                    FilledTonalButton(
                        onClick = onDelivered,
                        modifier = Modifier.weight(1f).height(48.dp),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.filledTonalButtonColors(
                            containerColor = StatusDeliveredBg,
                            contentColor = StatusDeliveredContent
                        )
                    ) {
                        Icon(Icons.Filled.Check, contentDescription = null, modifier = Modifier.size(18.dp))
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Delivered", fontWeight = FontWeight.Bold)
                    }
                }
            }
        }
    }

    // ── Contact action sheet ─────────────────────────────────────────────
    if (showContactSheet) {
        ContactActionSheet(
            onDismiss = { showContactSheet = false },
            onAction  = { action ->
                showContactSheet = false
                val message = buildMessage(settingsPrefs.read())
                val result  = launchContactAction(context, action, request.phoneNumber, message)
                val toast   = when (result) {
                    ContactActionResult.Success              -> null
                    ContactActionResult.InvalidPhone         -> "Invalid phone number"
                    ContactActionResult.WhatsAppNotInstalled -> "WhatsApp not installed"
                    ContactActionResult.NoHandler            -> "No app found to handle this action"
                }
                toast?.let { Toast.makeText(context, it, Toast.LENGTH_SHORT).show() }
            }
        )
    }
}

