enum class FilterTag(val label: String) {
    ALL("All"),
    TODAY("Today"),
    PENDING("Pending"),
    DELIVERED("Delivered")
}

// ══════════════════════════════════════════════════════════════════════════════
// ── BOTTOM NAVIGATION BAR ───────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

@Composable
fun MedQueueBottomBar(currentScreen: Screen, onNavigate: (Screen) -> Unit) {
    NavigationBar(
        containerColor = MaterialTheme.colorScheme.surface,
        tonalElevation = 4.dp
    ) {
        NavigationBarItem(
            selected = currentScreen is Screen.Home,
            onClick  = { onNavigate(Screen.Home) },
            icon     = { Icon(Icons.Filled.Home, contentDescription = "Home") },
            label    = { Text("Home") },
            colors   = NavigationBarItemDefaults.colors(
                selectedIconColor   = MaterialTheme.colorScheme.onPrimary,
                selectedTextColor   = MaterialTheme.colorScheme.primary,
                indicatorColor      = MaterialTheme.colorScheme.primary
            )
        )
        NavigationBarItem(
            selected = currentScreen is Screen.RequestList,
            onClick  = { onNavigate(Screen.RequestList) },
            icon     = { Icon(Icons.AutoMirrored.Filled.List, contentDescription = "Requests") },
            label    = { Text("Requests") },
            colors   = NavigationBarItemDefaults.colors(
                selectedIconColor   = MaterialTheme.colorScheme.onPrimary,
                selectedTextColor   = MaterialTheme.colorScheme.primary,
                indicatorColor      = MaterialTheme.colorScheme.primary
            )
        )
        NavigationBarItem(
            selected = currentScreen is Screen.Settings,
            onClick  = { onNavigate(Screen.Settings) },
            icon     = { Icon(Icons.Filled.Settings, contentDescription = "Settings") },
            label    = { Text("Settings") },
            colors   = NavigationBarItemDefaults.colors(
                selectedIconColor   = MaterialTheme.colorScheme.onPrimary,
                selectedTextColor   = MaterialTheme.colorScheme.primary,
                indicatorColor      = MaterialTheme.colorScheme.primary
            )
        )
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── REQUEST LIST SCREEN ─────────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RequestListScreen(
    requests: List<RequestEntity>,
    onAddClick: () -> Unit,
    onItemClick: (RequestEntity) -> Unit,
    bottomBar: @Composable () -> Unit = {}
) {
    var searchQuery by remember { mutableStateOf("") }
    var activeFilter by remember { mutableStateOf(FilterTag.ALL) }

    // Compute start-of-today once per recomposition
    val todayStart = remember {
        Calendar.getInstance().apply {
            set(Calendar.HOUR_OF_DAY, 0)
            set(Calendar.MINUTE, 0)
            set(Calendar.SECOND, 0)
            set(Calendar.MILLISECOND, 0)
        }.timeInMillis
    }

    val filteredRequests = remember(requests, searchQuery, activeFilter) {
        requests.filter { req ->
            // Search filter
            val matchesSearch = if (searchQuery.isBlank()) true
            else {
                val q = searchQuery.trim().lowercase()
                req.customerName.lowercase().contains(q) ||
                        req.phoneNumber.contains(q)
            }
            // Tag filter
            val matchesTag = when (activeFilter) {
                FilterTag.ALL       -> true
                FilterTag.TODAY     -> req.createdAt >= todayStart
                FilterTag.PENDING   -> req.status == RequestStatus.PENDING
                FilterTag.DELIVERED -> req.status == RequestStatus.DELIVERED
            }
            matchesSearch && matchesTag
        }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(" MedQueue", fontWeight = FontWeight.Bold) },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = TopBarContainer,
                    titleContentColor = TopBarContent
                )
            )
        },
        bottomBar = bottomBar,
        floatingActionButton = {
            ExtendedFloatingActionButton(
                onClick = onAddClick,
                icon = { Icon(Icons.Filled.Add, contentDescription = null) },
                text = { Text("Add Request") },
                containerColor = MaterialTheme.colorScheme.primary,
                contentColor   = MaterialTheme.colorScheme.onPrimary
            )
        },
        containerColor = MaterialTheme.colorScheme.background
    ) { padding ->
        Column(modifier = Modifier.padding(padding)) {

            // ── Search bar ───────────────────────────────────────────────
            OutlinedTextField(
                value = searchQuery,
                onValueChange = { searchQuery = it },
                placeholder = { Text("Search by name or phone") },
                leadingIcon = {
                    Icon(Icons.Filled.Search, contentDescription = "Search",
                        tint = MaterialTheme.colorScheme.onSurfaceVariant)
                },
                trailingIcon = {
                    if (searchQuery.isNotEmpty()) {
                        IconButton(onClick = { searchQuery = "" }) {
                            Icon(Icons.Filled.Close, contentDescription = "Clear")
                        }
                    }
                },
                singleLine = true,
                shape = RoundedCornerShape(14.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 8.dp)
            )

            // ── Filter chips row ─────────────────────────────────────────
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 4.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                FilterTag.entries.forEach { tag ->
                    FilterChip(
                        selected = activeFilter == tag,
                        onClick = { activeFilter = tag },
                        label = { Text(tag.label, fontWeight = FontWeight.Medium) },
                        colors = FilterChipDefaults.filterChipColors(
                            selectedContainerColor = MaterialTheme.colorScheme.primary,
                            selectedLabelColor = MaterialTheme.colorScheme.onPrimary
                        )
                    )
                }
            }

            // ── List content ─────────────────────────────────────────────
            if (filteredRequests.isEmpty()) {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        Text(
                            if (requests.isEmpty()) "No requests yet"
                            else "No matching requests",
                            style = MaterialTheme.typography.titleMedium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            if (requests.isEmpty()) "Tap + Add Request to get started"
                            else "Try a different search or filter",
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.outline
                        )
                    }
                }
            } else {
                LazyColumn(
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    items(filteredRequests, key = { it.id }) { request ->
                        RequestListItem(request = request, onClick = { onItemClick(request) })
                    }
                    // bottom spacer so FAB doesn't overlap last item
                    item { Spacer(modifier = Modifier.height(72.dp)) }
                }
            }
        }
    }
}

// ── List item card ───────────────────────────────────────────────────────────

@Composable
fun RequestListItem(request: RequestEntity, onClick: () -> Unit) {
    val dateFormat = remember { SimpleDateFormat("dd MMM yyyy, hh:mm a", Locale.getDefault()) }
    val displayName = request.customerName.ifBlank { "----" }
    val isPending = request.status == RequestStatus.PENDING

    val cardBg     = if (isPending) CardPendingBg else CardDeliveredBg
    val stripColor = if (isPending) StripePending  else StripeDelivered

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick),
        shape = RoundedCornerShape(14.dp),
        colors = CardDefaults.cardColors(containerColor = cardBg),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
    ) {
        Row(modifier = Modifier.fillMaxWidth().height(IntrinsicSize.Min)) {
            // Accent stripe
            Box(
                modifier = Modifier
                    .width(6.dp)
                    .fillMaxHeight()
                    .background(stripColor, RoundedCornerShape(topStart = 14.dp, bottomStart = 14.dp))
            )
            // Content
            Column(
                modifier = Modifier
                    .weight(1f)
                    .padding(start = 12.dp, end = 16.dp, top = 14.dp, bottom = 14.dp)
            ) {
                // Row 1: Name + Status
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = displayName,
                        style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.weight(1f, fill = false)
                    )
                    Spacer(modifier = Modifier.width(10.dp))
                    StatusBadge(status = request.status)
                }

                Spacer(modifier = Modifier.height(10.dp))

                // Row 2: Phone
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(
                        Icons.Filled.Phone,
                        contentDescription = null,
                        modifier = Modifier.size(15.dp),
                        tint = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        text = request.phoneNumber,
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }

                Spacer(modifier = Modifier.height(6.dp))

                // Row 3: Medicines
                Text(
                    text = "  ${request.medicineName}",
                    style = MaterialTheme.typography.bodyMedium,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    color = MaterialTheme.colorScheme.onSurface
                )

                Spacer(modifier = Modifier.height(10.dp))

                // Row 4: Date
                Text(
                    text = "  ${dateFormat.format(Date(request.createdAt))}",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.outline
                )
            }
        }
    }
}

// ── Status badge (bold orange / green pill) ──────────────────────────────────

@Composable
private fun StatusBadge(status: RequestStatus) {
    val isPending = status == RequestStatus.PENDING
    Surface(
        shape = RoundedCornerShape(20.dp),
        color = if (isPending) StatusPendingBg else StatusDeliveredBg,
        shadowElevation = 1.dp
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 5.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            if (!isPending) {
                Icon(
                    Icons.Filled.Check,
                    contentDescription = null,
                    modifier = Modifier.size(14.dp),
                    tint = StatusDeliveredContent
                )
            }
            Text(
                text = if (isPending) "PENDING" else "DELIVERED",
                style = MaterialTheme.typography.labelSmall.copy(fontWeight = FontWeight.Bold),
                color = if (isPending) StatusPendingContent else StatusDeliveredContent
            )
        }
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── HOME SCREEN (New Request) ───────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreen(onSave: (String, String, String) -> Unit, onBack: () -> Unit, bottomBar: @Composable () -> Unit = {}) {
    val context = LocalContext.current
    var name       by remember { mutableStateOf("") }
    var phone      by remember { mutableStateOf("") }
    var medicine   by remember { mutableStateOf("") }
    var phoneError by remember { mutableStateOf("") }
    var medicineError by remember { mutableStateOf("") }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("New Request") },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = TopBarContainer,
                    titleContentColor = TopBarContent,
                    navigationIconContentColor = TopBarContent
                )
            )
        },
        bottomBar = bottomBar
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 12.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // ── Description banner ───────────────────────────────────────
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(14.dp),
                color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.35f)
            ) {
                Row(
                    modifier = Modifier.padding(16.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Text("", style = MaterialTheme.typography.headlineSmall)
                    Text(
                        "Fill in the customer and medicine details to create a new request.",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                }
            }

            // ── Customer details card ────────────────────────────────────
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    Text(
                        "  Customer Details",
                        style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.primary
                    )
                    Text(
                        "Who is this request for?",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.outline
                    )
                    Spacer(modifier = Modifier.height(6.dp))
                    OutlinedTextField(
                        value = name,
                        onValueChange = { name = it },
                        label = { Text("Customer Name (Optional)") },
                        leadingIcon = { Icon(Icons.Filled.Person, contentDescription = null, tint = MaterialTheme.colorScheme.onSurfaceVariant) },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        shape = RoundedCornerShape(12.dp)
                    )
                    OutlinedTextField(
                        value = phone,
                        onValueChange = { raw ->
                            phone = raw.filter { it.isDigit() }
                            if (phone.isNotEmpty()) phoneError = ""
                        },
                        label = { Text("Phone Number *") },
                        leadingIcon = { Icon(Icons.Filled.Phone, contentDescription = null, tint = MaterialTheme.colorScheme.onSurfaceVariant) },
                        prefix = { Text("+91  ", style = MaterialTheme.typography.bodyLarge, color = MaterialTheme.colorScheme.onSurfaceVariant) },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        isError = phoneError.isNotEmpty(),
                        supportingText = if (phoneError.isNotEmpty()) {
                            { Text(phoneError, color = MaterialTheme.colorScheme.error) }
                        } else {
                            { Text("10-digit mobile number") }
                        },
                        shape = RoundedCornerShape(12.dp)
                    )
                }
            }

            // ── Medicine details card ────────────────────────────────────
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    Text(
                        "  Medicine Details",
                        style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.primary
                    )
                    Text(
                        "List the medicines the customer needs",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.outline
                    )
                    Spacer(modifier = Modifier.height(6.dp))
                    OutlinedTextField(
                        value = medicine,
                        onValueChange = {
                            medicine = it
                            if (medicine.isNotEmpty()) medicineError = ""
                        },
                        label = { Text("Medicines *") },
                        placeholder = { Text("e.g.\nParacetamol 500mg\nAmoxicillin 250mg") },
                        modifier = Modifier
                            .fillMaxWidth()
                            .heightIn(min = 130.dp),
                        minLines = 4,
                        maxLines = 8,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Text),
                        singleLine = false,
                        isError = medicineError.isNotEmpty(),
                        supportingText = if (medicineError.isNotEmpty()) {
                            { Text(medicineError, color = MaterialTheme.colorScheme.error) }
                        } else {
                            { Text("Enter each medicine on a new line") }
                        },
                        shape = RoundedCornerShape(12.dp)
                    )
                }
            }

            // ── Action buttons ───────────────────────────────────────────
            Spacer(modifier = Modifier.height(4.dp))

            Button(
                onClick = {
                    phoneError = ""
                    medicineError = ""
                    when {
                        phone.isBlank()    -> phoneError = "Phone number is required"
                        phone.length < 10  -> phoneError = "Enter a valid 10-digit phone number"
                        medicine.isBlank() -> medicineError = "At least one medicine is required"
                        else               -> onSave(name, phone, medicine)
                    }
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(52.dp),
                shape = RoundedCornerShape(14.dp)
            ) {
                Icon(Icons.Filled.Check, contentDescription = null, modifier = Modifier.size(20.dp))
                Spacer(modifier = Modifier.width(8.dp))
                Text("Save Request", fontWeight = FontWeight.Bold, style = MaterialTheme.typography.titleSmall)
            }

            TextButton(
                onClick = onBack,
                modifier = Modifier.fillMaxWidth()
            ) { Text("Cancel") }

            Spacer(modifier = Modifier.height(8.dp))
        }
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── REQUEST DETAIL SCREEN ───────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RequestDetailScreen(
    request: RequestEntity,
    settingsPrefs: SettingsPrefs,
    onEdit: () -> Unit,
    onDelivered: () -> Unit,
    onDelete: () -> Unit,
    onBack: () -> Unit
) {
    val context = LocalContext.current
    var showContactSheet by remember { mutableStateOf(false) }
    val dateFormat = remember { SimpleDateFormat("dd MMM yyyy, hh:mm a", Locale.getDefault()) }
    val displayName = request.customerName.ifBlank { "----" }

    val isPending = request.status == RequestStatus.PENDING

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Request Detail") },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                actions = {
                    IconButton(onClick = onEdit) {
                        Icon(Icons.Filled.Edit, contentDescription = "Edit")
                    }
                    IconButton(onClick = onDelete) {
                        Icon(Icons.Filled.Delete, contentDescription = "Delete",
                            tint = TopBarContent.copy(alpha = 0.7f))
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = TopBarContainer,
                    titleContentColor = TopBarContent,
                    navigationIconContentColor = TopBarContent,
                    actionIconContentColor = TopBarContent
                )
            )
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Customer info card with status-coloured background
            val infoBg = if (isPending) CardPendingBg else CardDeliveredBg
            Card(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                colors = CardDefaults.cardColors(containerColor = infoBg),
                elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)
            ) {
                Column(modifier = Modifier.padding(20.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            text = displayName,
                            style = MaterialTheme.typography.titleLarge.copy(fontWeight = FontWeight.Bold),
                            modifier = Modifier.weight(1f, fill = false)
                        )
                        Spacer(modifier = Modifier.width(12.dp))
                        StatusBadge(status = request.status)
                    }
                    Spacer(modifier = Modifier.height(12.dp))
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            Icons.Filled.Phone,
                            contentDescription = null,
                            modifier = Modifier.size(18.dp),
                            tint = MaterialTheme.colorScheme.primary
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        Text(
                            text = request.phoneNumber,
                            style = MaterialTheme.typography.bodyLarge,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = "  ${dateFormat.format(Date(request.createdAt))}",
                        style = MaterialTheme.typography.labelMedium,
                        color = MaterialTheme.colorScheme.outline
                    )
                }
            }

            // Medicines card
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(modifier = Modifier.padding(20.dp)) {
                    Text(
                        text = " Medicines",
                        style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.primary
                    )
                    Spacer(modifier = Modifier.height(10.dp))
                    Text(
                        text = request.medicineName,
                        style = MaterialTheme.typography.bodyLarge
                    )
                }
            }

            // Action buttons
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Button(
                    onClick = { showContactSheet = true },
                    modifier = Modifier.weight(1f).height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Icon(Icons.AutoMirrored.Filled.Send, contentDescription = null, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Contact", fontWeight = FontWeight.Bold)
                }
                if (isPending) {
                    FilledTonalButton(
                        onClick = onDelivered,
                        modifier = Modifier.weight(1f).height(48.dp),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.filledTonalButtonColors(
                            containerColor = StatusDeliveredBg,
                            contentColor = StatusDeliveredContent
                        )
                    ) {
                        Icon(Icons.Filled.Check, contentDescription = null, modifier = Modifier.size(18.dp))
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Delivered", fontWeight = FontWeight.Bold)
                    }
                }
            }
        }
    }

    // ── Contact action sheet ─────────────────────────────────────────────
    if (showContactSheet) {
        ContactActionSheet(
            onDismiss = { showContactSheet = false },
            onAction  = { action ->
                showContactSheet = false
                val message = buildMessage(settingsPrefs.read())
                val result  = launchContactAction(context, action, request.phoneNumber, message)
                val toast   = when (result) {
                    ContactActionResult.Success              -> null
                    ContactActionResult.InvalidPhone         -> "Invalid phone number"
                    ContactActionResult.WhatsAppNotInstalled -> "WhatsApp not installed"
                    ContactActionResult.NoHandler            -> "No app found to handle this action"
                }
                toast?.let { Toast.makeText(context, it, Toast.LENGTH_SHORT).show() }
            }
        )
    }
}

