        Column(modifier = Modifier.padding(bottom = 24.dp)) {
            Text(
                text = "Send message via",
                style = MaterialTheme.typography.titleSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.padding(horizontal = 24.dp, vertical = 8.dp)
            )
            ListItem(
                headlineContent = { Text("WhatsApp") },
                leadingContent = {
                    Icon(
                        Icons.AutoMirrored.Filled.Send,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.primary
                    )
                },
                modifier = Modifier.clickable { onAction(ContactAction.WHATSAPP) }
            )
            ListItem(
                headlineContent = { Text("SMS") },
                leadingContent = {
                    Icon(
                        Icons.AutoMirrored.Filled.Send,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.secondary
                    )
                },
                modifier = Modifier.clickable { onAction(ContactAction.SMS) }
            )
            ListItem(
                headlineContent = { Text("Call") },
                leadingContent = {
                    Icon(
                        Icons.Filled.Phone,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.tertiary
                    )
                },
                modifier = Modifier.clickable { onAction(ContactAction.CALL) }
            )
        }
    }
}

