                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = TopBarContainer,
                    titleContentColor = TopBarContent,
                    navigationIconContentColor = TopBarContent
                )
            )
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    Text("Customer Details",
                        style = MaterialTheme.typography.titleSmall,
                        color = MaterialTheme.colorScheme.primary)
                    OutlinedTextField(
                        value = name,
                        onValueChange = { name = it },
                        label = { Text("Customer Name (Optional)") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        shape = RoundedCornerShape(12.dp)
                    )
                    OutlinedTextField(
                        value = phone,
                        onValueChange = { raw ->
                            phone = raw.filter { it.isDigit() }
                            if (phone.isNotEmpty()) phoneError = ""
                        },
                        label = { Text("Phone Number") },
                        modifier = Modifier.fillMaxWidth(),
                        singleLine = true,
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        isError = phoneError.isNotEmpty(),
                        supportingText = if (phoneError.isNotEmpty()) {
                            { Text(phoneError, color = MaterialTheme.colorScheme.error) }
                        } else null,
                        shape = RoundedCornerShape(12.dp)
                    )
                }
            }

            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    Text("Medicine Details",
                        style = MaterialTheme.typography.titleSmall,
                        color = MaterialTheme.colorScheme.primary)
                    OutlinedTextField(
                        value = medicine,
                        onValueChange = { medicine = it },
                        label = { Text("Medicines") },
                        placeholder = { Text("e.g.\nParacetamol 500mg\nAmoxicillin 250mg") },
                        modifier = Modifier.fillMaxWidth().heightIn(min = 120.dp),
                        minLines = 4,
                        maxLines = 8,
                        singleLine = false,
                        shape = RoundedCornerShape(12.dp)
                    )
                }
            }

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Button(
                    onClick = {
                        phoneError = ""
                        when {
                            phone.isBlank()    -> phoneError = "Phone number is required"
                            phone.length < 10  -> phoneError = "Enter a valid 10-digit phone number"
                            medicine.isBlank() -> Toast.makeText(context, "Medicine is required", Toast.LENGTH_SHORT).show()
                            else               -> onSave(name, phone, medicine)
                        }
                    },
                    modifier = Modifier.weight(1f).height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) { Text("Save Changes", fontWeight = FontWeight.Bold) }

                OutlinedButton(
                    onClick = onBack,
                    modifier = Modifier.weight(1f).height(48.dp),
                    shape = RoundedCornerShape(12.dp)
                ) { Text("Cancel") }
            }
        }
    }
}

// ══════════════════════════════════════════════════════════════════════════════
// ── SETTINGS SCREEN ─────────────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════════

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SettingsScreen(settingsPrefs: SettingsPrefs, onBack: () -> Unit, bottomBar: @Composable () -> Unit = {}) {
    val context = LocalContext.current
    val current  = remember { settingsPrefs.read() }
    var shopName      by remember { mutableStateOf(current.shopName) }
    var contact1Name  by remember { mutableStateOf(current.contact1Name) }
    var contact1Phone by remember { mutableStateOf(current.contact1Phone) }
    var contact2Name  by remember { mutableStateOf(current.contact2Name) }
    var contact2Phone by remember { mutableStateOf(current.contact2Phone) }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Settings") },
                navigationIcon = {
                    IconButton(onClick = onBack) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = TopBarContainer,
                    titleContentColor = TopBarContent,
                    navigationIconContentColor = TopBarContent
                )
            )
        },
        bottomBar = bottomBar
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp, vertical = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Shop info card
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(modifier = Modifier.padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
                    Text("Shop Information",
                        style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.primary)
                    OutlinedTextField(value = shopName, onValueChange = { shopName = it },
                        label = { Text("Shop Name") }, modifier = Modifier.fillMaxWidth(),
                        singleLine = true, shape = RoundedCornerShape(12.dp))
                }
            }

            // Contact 1 card
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(modifier = Modifier.padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
                    Text("Contact 1",
                        style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.primary)
                    OutlinedTextField(value = contact1Name, onValueChange = { contact1Name = it },
                        label = { Text("Name") }, modifier = Modifier.fillMaxWidth(),
                        singleLine = true, shape = RoundedCornerShape(12.dp))
                    OutlinedTextField(value = contact1Phone, onValueChange = { contact1Phone = it },
                        label = { Text("Phone") }, modifier = Modifier.fillMaxWidth(),
                        singleLine = true, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        shape = RoundedCornerShape(12.dp))
                }
            }

            // Contact 2 card
            ElevatedCard(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(16.dp),
                elevation = CardDefaults.elevatedCardElevation(defaultElevation = 2.dp)
            ) {
                Column(modifier = Modifier.padding(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
                    Text("Contact 2",
                        style = MaterialTheme.typography.titleSmall.copy(fontWeight = FontWeight.SemiBold),
                        color = MaterialTheme.colorScheme.primary)
                    OutlinedTextField(value = contact2Name, onValueChange = { contact2Name = it },
                        label = { Text("Name") }, modifier = Modifier.fillMaxWidth(),
                        singleLine = true, shape = RoundedCornerShape(12.dp))
                    OutlinedTextField(value = contact2Phone, onValueChange = { contact2Phone = it },
                        label = { Text("Phone") }, modifier = Modifier.fillMaxWidth(),
                        singleLine = true, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Phone),
                        shape = RoundedCornerShape(12.dp))
                }
            }

            Button(
                onClick = {
                    settingsPrefs.save(AppSettings(shopName, contact1Name, contact1Phone, contact2Name, contact2Phone))
                    Toast.makeText(context, "Settings saved", Toast.LENGTH_SHORT).show()
                    onBack()
                },
                modifier = Modifier.fillMaxWidth().height(48.dp),
                shape = RoundedCornerShape(12.dp)
            ) { Text("Save Settings", fontWeight = FontWeight.Bold) }

            Spacer(modifier = Modifier.height(16.dp))
        }
    }
}
